//! @generated by xtask split-relics.
use super::prelude::*;

pub(crate) fn on_after_card_played_pocketwatch(
    state: &mut CombatState,
    _ctx: &CardEventCtx,
) -> EffectResult {
    if !player_owns_relic(state, crate::RelicKind::Pocketwatch) {
        return EffectResult::NotImplemented;
    }
    if let Some(r) = pocketwatch_relic_mut(state) {
        let this_turn = (r.counter & 0xff).saturating_add(1).min(0xff);
        r.counter = (r.counter & !0xff) | this_turn;
    }
    EffectResult::Resolved
}

pub(crate) fn on_before_side_turn_start_pocketwatch(
    state: &mut CombatState,
    side: Side,
) -> EffectResult {
    if side != Side::Player {
        return EffectResult::NotImplemented;
    }
    if let Some(r) = pocketwatch_relic_mut(state) {
        let this_turn = r.counter & 0xff;
        r.counter = (this_turn & 0xff) << 8;
    }
    EffectResult::Resolved
}

pub(crate) fn on_modify_hand_draw_pocketwatch(state: &CombatState, current_draw: i32) -> i32 {
    if !player_owns_relic(state, crate::RelicKind::Pocketwatch) {
        return current_draw;
    }
    if state.turn_number() <= 1 {
        return current_draw;
    }
    let Some(last_turn) = pocketwatch_cards_last_turn(state) else {
        return current_draw;
    };
    if last_turn <= POCKETWATCH_CARD_THRESHOLD {
        current_draw + POCKETWATCH_EXTRA_DRAW
    } else {
        current_draw
    }
}

pub(crate) fn on_after_combat_end_pocketwatch(state: &mut CombatState) -> EffectResult {
    let Some(r) = pocketwatch_relic_mut(state) else {
        return EffectResult::NotImplemented;
    };
    r.counter = 0;
    EffectResult::Resolved
}

pub(crate) fn install() {
    register_after_card_played(
        RelicId::Pocketwatch,
        on_after_card_played_pocketwatch as AfterCardPlayedFn,
    );
    register_before_side_turn_start(
        RelicId::Pocketwatch,
        on_before_side_turn_start_pocketwatch as BeforeSideTurnStartFn,
    );
    register_owned_modify_hand_draw(
        RelicId::Pocketwatch,
        crate::RelicKind::Pocketwatch,
        on_modify_hand_draw_pocketwatch as ModifyHandDrawFn,
    );
    register_owned_after_combat_end(
        RelicId::Pocketwatch,
        crate::RelicKind::Pocketwatch,
        on_after_combat_end_pocketwatch as AfterCombatEndFn,
    );
}
